import java.util.*;

public class AccountsMerge {

    static class DSU {
        int[] p, r;
        DSU(int n){ p=new int[n]; r=new int[n]; for(int i=0;i<n;i++) p[i]=i;}
        int find(int x){ return p[x]==x? x : (p[x]=find(p[x])); }
        void union(int a,int b){
            int ra=find(a), rb=find(b);
            if(ra==rb) return;
            if(r[ra]<r[rb]) p[ra]=rb;
            else if(r[ra]>r[rb]) p[rb]=ra;
            else { p[rb]=ra; r[ra]++; }
        }
    }

    public static List<List<String>> merge(List<List<String>> accounts) {
        Map<String,Integer> emailIndex = new HashMap<>();
        Map<String,String>  emailName  = new HashMap<>();
        int idx = 0;

        // First pass: map every unique email to an index, keep owner name
        for (List<String> acc : accounts) {
            String name = acc.get(0);
            for (int i = 1; i < acc.size(); i++) {
                String email = acc.get(i);
                if (!emailIndex.containsKey(email)) {
                    emailIndex.put(email, idx++);
                    emailName.put(email, name);
                }
            }
        }

        DSU dsu = new DSU(idx);

        // Union emails that belong to the same account
        for (List<String> acc : accounts) {
            String firstEmail = acc.get(1);
            int firstIdx = emailIndex.get(firstEmail);
            for (int i = 2; i < acc.size(); i++) {
                dsu.union(firstIdx, emailIndex.get(acc.get(i)));
            }
        }

        // Collect emails under their root parent
        Map<Integer, TreeSet<String>> groups = new HashMap<>();
        for (String email : emailIndex.keySet()) {
            int root = dsu.find(emailIndex.get(email));
            groups.computeIfAbsent(root, k -> new TreeSet<>()).add(email);
        }

        // Build merged accounts
        List<List<String>> res = new ArrayList<>();
        for (TreeSet<String> emails : groups.values()) {
            List<String> merged = new ArrayList<>();
            String name = emailName.get(emails.first());
            merged.add(name);
            merged.addAll(emails);
            res.add(merged);
        }
        return res;
    }

    public static void main(String[] args) {
        List<List<String>> accounts = List.of(
                List.of("John", "a@gmail.com", "b@gmail.com"),
                List.of("John", "b@gmail.com", "c@gmail.com"),
                List.of("Mary", "x@gmail.com")
        );
        System.out.println("Merged accounts:");
        for (List<String> acc : merge(accounts))
            System.out.println(acc);
    }
}

import java.util.*;
class  AnagramsTogether
{
	 public static  List<List<String>> groupAnagrams(String[] strs) 
	{
        Map<String,List<String>>map=new HashMap<>();
        for(String e:strs)
		{
            char ch[]=e.toCharArray();
            Arrays.sort(ch);
            String sorted=new String(ch);
            if(!map.containsKey(sorted))
			{
                map.put(sorted,new ArrayList<String>());
            }
            map.get(sorted).add(e);
        }
		for(Map.Entry<String,List<String>> m:map.entrySet())
		{
			System.out.println(m.getKey()+"	"+m.getValue());
		}
        return new LinkedList<>(map.values());
    }
	public static void main(String[] args) 
	{
		Scanner sc=new Scanner(System.in);
		String s[]=sc.nextLine().split(" ");
		System.out.println(groupAnagrams(s));
	}
}

