import java.util.*;
class  CenterofStar
{
	 public static int findCenter(int[][] a)
	 {
        Map<Integer, Integer> m = new HashMap<>();

        for (int[] edge : a) 
		{
            m.put(edge[0], m.getOrDefault(edge[0], 0) + 1);
            m.put(edge[1], m.getOrDefault(edge[1], 0) + 1);
        }

        for (int node : m.keySet()) 
		{
			if (m.get(node) == a.length)
			{
                return node;
            }
        }
        return -1;
    }
	public static void main(String[] args) 
	{
		Scanner sc=new Scanner(System.in);
		int edges=sc.nextInt();
		int a[][]=new int[edges][2];

		for(int i=0;i<edges;i++)
		{
			for(int j=0;j<2;j++)
			{
				a[i][j]=sc.nextInt();
			}
		}
		System.out.println(findCenter(a));
	}
}

