import java.util.*;

public class DropElementsFromArray 
{
    public static void main(String[] args) 
	{
        Scanner s = new Scanner(System.in);

        // Read size of array A
        int n = s.nextInt();
        int[] A = new int[n];

        // Read elements of array A
        for (int i = 0; i < n; i++) {
            A[i] = s.nextInt();
        }

        // Read size of array X (indices to remove)
        int m = s.nextInt();
        Set<Integer> indicesToDrop = new HashSet<>();

        // Read elements of array X
        for (int i = 0; i < m; i++) 
		{
            int index = s.nextInt();
            indicesToDrop.add(index);
        }

        // Print the elements that are not in the drop list
        for (int i = 0; i < n; i++) 
		{
            if (!indicesToDrop.contains(i)) 
			{
                System.out.print(A[i] + " ");
            }
        }
    }
}

import java.util.*;
public class FriendCircles 
{
        static int[] p, size;
        static int find(int x)
		{ 
			while(p[x]>=0)
				x=p[x];
			return x;
		}
        static void union(int a,int b)
		{
            int ra=find(a);
			int rb=find(b);
            if(ra==rb) 
				return;
            if(size[ra]<size[rb])
			{
				size[rb]++;
				p[ra]=rb;
			}
            else 
            {
				size[ra]++;
				p[rb]=ra; 
			}
        }
        public static int findCircleNum(int[][] M) 
		{
			int n=M.length;
			p = new int[n]; 
			size = new int[n]; 
			for(int i=0;i<n;i++)
			{
				p[i]=-1;
				size[i]=1;
			}
			for (int i = 0; i < n; i++)
            for (int j = i + 1; j < n; j++)
                if (M[i][j] == 1) 
					union(i, j);

        int circles = 0;
        for (int i = 0; i < n; i++)
		{
            if (find(i) == i) 
				circles++;
		}
        return circles;
    }
    public static void main(String[] args) 
	{
		Scanner sc=new Scanner(System.in);
		int n=sc.nextInt();
		int M[][]=new int[n][n];
		for(int i=0;i<n;i++)
			for(int j=0;j<n;j++)
				M[i][j]=sc.nextInt();
        System.out.println(findCircleNum(M)); 
    }
}
