import java.util.*;
class  FriendGroups
{
	static int[] p;
    static int find(int x)
	{ 
		while(p[x]>=0)
			x=p[x];
		return x;
	}
    static void union(int a,int b)
	{
        int ra=find(a);
		int rb=find(b);
        if(ra==rb) 
			return;
        p[ra]=rb;
	}
    static boolean same(int a, int b) 
	{
		return find(a) == find(b); 
	}
    /* returns false if any enemy pair ends up in same component */
    public static boolean constraintsValid(int n, int[][] friends, int[][] enemies)
	{
		p = new int[n]; 
		for(int i=0;i<n;i++)
		{
				p[i]=-1;
		}

        for (int[] f : friends) 
			union(f[0], f[1]);

		for (int[] e : enemies)
		{
            if (same(e[0], e[1])) 
				return false;
		}
        return true;
    }

    public static void main(String[] args)
	{
		Scanner sc=new Scanner(System.in);
		int fc=sc.nextInt();
		int[][] friends = new int[fc][2];
		for(int i=0;i<fc;i++)
				for(int j=0;j<2;j++)
					friends[i][j]=sc.nextInt();
		int ec=sc.nextInt();
        int[][] enemies = new int[ec][2];
		for(int i=0;i<ec;i++)
				for(int j=0;j<2;j++)
					enemies[i][j]=sc.nextInt();
        System.out.println(constraintsValid(fc+ec, friends, enemies)); // false
    }
}

