import java.util.*;
public class GraphCycle 
{
        static int[] p, size;
        static int find(int x)
		{ 
			while(p[x]>=0)
				x=p[x];
			return x;
		}
        static boolean union(int a,int b)
		{
            int ra=find(a);
			int rb=find(b);
            if(ra==rb) 
				return false;
            if(size[ra]<size[rb])
			{
				size[rb]++;
				p[ra]=rb;
			}
            else 
            {
				size[ra]++;
				p[rb]=ra; 
			}
			return true;
        }
		public static boolean hasCycle(int n, int[][] edges) 
		{
			p = new int[n]; 
			size = new int[n]; 
			for(int i=0;i<n;i++)
			{
				p[i]=-1;
				size[i]=1;
			}
			for (int[] e : edges) 
			{
