class  GroupWords
{
    static int[] p;
    static int find(int x)
	{ 
		while(p[x]>=0)
			x=p[x];
		return x;
	}
    static void union(int a,int b)
	{
        int ra=find(a);
	    int rb=find(b);
        if(ra==rb) 
			return;
        p[ra]=rb;
	}


    /* returns number of anagram groups */
    public static int groupCount(String[] words) 
	{
        int n = words.length;
        p = new int[n]; 
		for(int i=0;i<n;i++)
		{
				p[i]=-1;
		}

