import java.util.*;

class ActivitySelection 
{

    // Define a class to represent an Activity with start and finish times
    static class Activity 
	{
        int start, finish;

        Activity(int start, int finish) 
		{
            this.start = start;
            this.finish = finish;
        }
    }

    // Custom comparator to sort activities by finish time
    static class ActivityComparator implements Comparator<Activity> 
	{
        public int compare(Activity a1, Activity a2) 
		{
            return a1.finish - a2.finish;
        }
    }

    public static void main(String[] args) 
	{
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        Activity[] activities = new Activity[n];
        for (int i = 0; i < n; i++) {
            int start = scanner.nextInt();
            int finish = scanner.nextInt();
            activities[i] = new Activity(start, finish);
        }

        // Step 1: Sort activities by finish time
        Arrays.sort(activities, new ActivityComparator());

        // Step 2: Select the first activity
        List<Activity> selected = new ArrayList<>();
        selected.add(activities[0]);
        int lastFinishTime = activities[0].finish;

        // Step 3 to 5: Check for compatible activities
        for (int i = 1; i < n; i++) 
		{
            if (activities[i].start >= lastFinishTime) 
			{
                selected.add(activities[i]);
                lastFinishTime = activities[i].finish;
            }
        }

        // Step 6: Print the selected activities
        for (Activity act : selected) 
		{
            System.out.println("Start: " + act.start + ", Finish: " + act.finish);
        }
    }
}

import java.util.*;
class  BestTime
{
	 public static int maxProfit(int prices[]) 
	 {
        int minprice = Integer.MAX_VALUE;
        int maxprofit = 0;
        for (int i = 0; i < prices.length; i++) 
		{
            if (prices[i] < minprice) 
				minprice = prices[i];
            else if (prices[i] - minprice > maxprofit) 
				maxprofit = prices[i] - minprice;
        }
        return maxprofit;
    }
	public static void main(String[] args) 
	{
		Scanner sc=new Scanner(System.in);
		int n=sc.nextInt();
		int p[]=new int[n];
		for(int i=0;i<n;i++)
			p[i]=sc.nextInt();
		System.out.println(maxProfit(p));
	}
}

