        for(int i=1; i<S.length(); i++)
		{
            if(S.charAt(i) == S.charAt(i-1))
				dp[i] = dp[i-1] + 1;
            else 
				dp[i] = 1;
            res += dp[i];
        }
        return res;
    }
	public static void main(String[] args) 
	{
