import java.util.*;

public class CourseSchedule 
{
    public static List<Integer> canFinish(int numCourses, int[][] prerequisites) 
	{
        int adjList[][]=new int[numCourses][numCourses];

        // Populate the adjacency list with prerequisites
        int[] inDegree = new int[numCourses];
        for (int[] prerequisite : prerequisites) 
		{
            int u = prerequisite[0];
            int v = prerequisite[1];
            adjList[v][u]=1;
            inDegree[u]++;
        }

        // Perform a topological sort to find the order in which the courses should be taken
        Queue<Integer> queue = new LinkedList<>();
        for (int i = 0; i < numCourses; i++) 
		{
            if (inDegree[i] == 0) 
			{
                queue.offer(i);
            }
        }

        int count = 0;
		//int[] order = new int[numCourses];
		List<Integer> order=new ArrayList<>();
        int index = 0;
        while (!queue.isEmpty()) 
		{
            int u = queue.poll();
            count++;
			//order[index++] = u;
			order.add(u);
            for (int v=0;v<numCourses;v++) 
			{

                if (adjList[u][v]==1&&--inDegree[v] == 0) 
				{
                    queue.offer(v);
                }
            }
        }
        if(count == numCourses)
		{
//			for(int i=0;i<count;i++)
//				System.out.print(order[i]+" ");
//			System.out.println(order);
			return order;
		}
		else
		{
			return new ArrayList<Integer>();
		}
    }
	public static void main(String[] args) 
	{
		Scanner s=new Scanner(System.in);
		int nc=s.nextInt();
		int c=s.nextInt();
		int prereq[][]=new int[c][2];
		for(int i=0;i<c;i++)
		{
			for(int j=0;j<2;j++)
			{
				prereq[i][j]=s.nextInt();
			}
		}
		System.out.println(canFinish(nc, prereq));
	}
}

