/*
You are climbing a staircase. It takes n steps to reach the top.
Each time you can either climb 1 or 2 steps. In how many distinct ways
can you climb to the top?
Write a java program using Dynamic Programming Memoization Approach
to implement climbing staircase problem. 

Example 1:

Input: n = 2
Output: 2
Explanation: There are two ways to climb to the top.
1. 1 step + 1 step
2. 2 steps

Example 2:
Input: n = 3
Output: 3
Explanation: There are three ways to climb to the top.
1. 1 step + 1 step + 1 step
2. 1 step + 2 steps
3. 2 steps + 1 step
*/
import java.util.*;
class  DPClimbingStairs2
{
	public static int climbStairs(int n) 
	{
        int dp[] = new int[n + 1];
        return climb(0, n, dp);
    }

    public static int climb(int i, int n, int dp[]) 
	{
        if (i > n) 
		{
            return 0;
        }
        if (i == n) 
		{
            return 1;
        }
        if (dp[i] > 0) 
		{
            return dp[i];
        }
        dp[i] = climb(i + 1, n, dp) + climb(i + 2, n, dp);
        return dp[i];
    }
	public static void main(String[] args) 
	{
		Scanner s=new Scanner(System.in);
		int n=s.nextInt();
		System.out.println(climbStairs(n));
	}
}

