/*
The Fibonacci numbers, commonly denoted F(n) form a sequence,
called the Fibonacci sequence, such that each number is the sum of the 
two preceding ones, starting from 0 and 1. That is,
F(1) = 0, F(2) = 1
F(n) = F(n - 1) + F(n - 2), for n > 2.
Given n, calculate F(n)  using Dynamic Programming Memoization Approach.


Example 1:
Input: n = 3
Output: 1
Explanation: F(3) = F(2) + F(1) = 1 + 0 = 1.

Example 2:
Input: n = 4
Output: 2
Explanation: F(4) = F(3) + F(2) = 1 + 1 = 2.

Example 3:
Input: n = 5
Output: 3
Explanation: F(5) = F(4) + F(3) = 2 + 1 = 3.
*/
import java.util.*;
class  DPFibonacci2
{
	public static int fib(int n) 
	{
        int[] dp=new int[n+1];
        for(int i=0;i<dp.length;i++)
		{
            dp[i]=-1;
        }
        int ans=fun(n,dp);
        return ans;
    }

    static int fun(int n,int[] dp)
	{
        if(n==1)
            return 0;
		if(n==2)
			return 1;
        if(dp[n]!=-1)
            return dp[n];
        return dp[n]=fun(n-1,dp)+fun(n-2,dp);
    }
	public static void main(String[] args) 
	{
		Scanner s=new Scanner(System.in);
		int n=s.nextInt();
		System.out.println(fib(n));
	}
}
