/*
You are a professional robber planning to rob houses along a street. 
Each house has a certain amount of money stashed, the only constraint 
stopping you from robbing each of them is that adjacent houses have 
security systems connected and it will automatically contact the police 
if two adjacent houses were broken into on the same night.

Given an integer array nums representing the amount of money of each
house, return the maximum amount of money you can rob tonight without
alerting the police.


Example 1:
Input: 
4
1 2 3 1
Output: 4
Explanation: Rob house 1 (money = 1) and then rob house 3 (money = 3).
Total amount you can rob = 1 + 3 = 4.
Example 2:

Input: 
5
2 7 9 3 1
Output: 12
Explanation: Rob house 1 (money = 2), rob house 3 (money = 9) and rob
house 5 (money = 1).
Total amount you can rob = 2 + 9 + 1 = 12.
Step-by-Step Example
Consider nums = [2, 7, 9, 3, 1]:

dp[0] = 2: Robbing the first house.
dp[1] = 7: Robbing the second house since it has more money.
dp[2] = max(7, 9 + 2) = 11: Robbing the first and third houses.
dp[3] = max(11, 3 + 7) = 11: Skipping the fourth house.
dp[4] = max(11, 1 + 11) = 12: Robbing the first, third, and fifth houses.
Output: 12
*/
import java.util.*;
class  HouseRobber
{
	public static int rob(int[] nums) 
	{
        int n = nums.length;

        if (n == 1)
		{
            return nums[0];
        }

        int[] dp = new int[n];

        dp[0] = nums[0];
        dp[1] = Math.max(nums[0], nums[1]);

        for (int i = 2; i < n; i++) 
		{
            dp[i] = Math.max(dp[i - 1], nums[i] + dp[i - 2]);
        }

        return dp[n - 1];        
    }
	public static void main(String[] args) 
	{
		Scanner sc = new Scanner(System.in);
        int n = sc.nextInt(); 
        int[] nums = new int[n];
        for (int i = 0; i < n; i++) 
		{
            nums[i] = sc.nextInt();
        }
        System.out.println(rob(nums));
	}
}

