1 3 5 7 9

5
1 3 5 7 9
4
2 4 8 10
1 2 3 4 5 7 8 9 10
*/


import java.util.*;
class node
{
	int data;
	node next;
}
class ListMerge 
{
	node create(node head, int x)
	{
		//create the node
		node nn=new node();
		nn.data=x;
		nn.next=null;

		//list is not present
		if(head==null)
		{
			head=nn;
			return head;
		}

		//list is already present

		node temp=head;
		while(temp.next!=null)
		{
			temp=temp.next;
		}
		temp.next=nn;
		return head;
	}

	void display(node head)
	{
		if(head==null)
		{
			System.out.println("List is not present");
			return;
		}
		node temp=head;
		while(temp!=null)
		{
			System.out.print(temp.data+" ");
			temp=temp.next;
		}
		System.out.println();
	}

	node merge(node h1,node h2)
	{
		if (h1==null) return h2;
		if (h2==null) return h1;
		node h3=null;

		if(h1.data<h2.data)
		{
			h3=h1;
			h1=h1.next;
		}
		else
		{
			h3=h2;
			h2=h2.next;
		}
		node h4=h3;
		while(h1!=null&&h2!=null)
		{
			if(h1.data<h2.data)
			{
				h4.next=h1;
				h1=h1.next;
			}
			else
			{
				h4.next=h2;
				h2=h2.next;
			}
			h4=h4.next;
		}
		if (h1!=null) 
			h4.next=h1;
		if (h2!=null) 
			h4.next=h2;

		return h3;
	}
	public static void main(String[] args) 
	{
		Scanner s=new Scanner(System.in);
		ListMerge lm=new ListMerge();
		int m=s.nextInt();
		node h1=null;

		for(int i=1;i<=m;i++)
		{
			int x=s.nextInt();
			h1=lm.create(h1,x);
		}
		int n=s.nextInt();
		node h2=null;

		for(int i=1;i<=n;i++)
		{
			int x=s.nextInt();
			h2=lm.create(h2,x);
		}
		node h3=lm.merge(h1,h2);
		lm.display(h3);
	}
}


