/*
You are given an m x n integer array grid. There is a robot initially located 
at the top-left corner (i.e., grid[0][0]). The robot tries to move to the 
bottom-right corner (i.e., grid[m - 1][n - 1]). The robot can only move 
either down or right at any point in time.

An obstacle and space are marked as 1 or 0 respectively in grid. A path
that the robot takes cannot include any square that is an obstacle.

Return the number of possible unique paths that the robot can take
to reach the bottom-right corner.

Example1
Input: obstacleGrid = [[0,0,0],[0,1,0],[0,0,0]]
Output: 2
Explanation: There is one obstacle in the middle of the 3x3 grid above.
There are two ways to reach the bottom-right corner:
1. Right -> Right -> Down -> Down
2. Down -> Down -> Right -> Right

Example2
Input: obstacleGrid = [[0,1],[0,0]]
Output: 1

Sample Input and Output:
input=3 3
0 0 0
0 1 0
0 0 0
output=2

input=2 2
0 1
0 0
output=1
*/
import java.util.*;
class  PathsWithObstacle
{
    public static int uniquePathsWithObstacles(int o[][]) 
	{
        int R = o.length;
        int C = o[0].length;

        // If the starting cell has an obstacle, then simply return as there 
		// would be no paths to the destination.
        if (o[0][0] == 1) 
		{
            return 0;
        }

        // Number of ways of reaching the starting cell = 1.
        o[0][0] = 1;

        // Filling the values for the first column
        for (int i = 1; i < R; i++) 
		{
            o[i][0] = (o[i][0] == 0 && o[i - 1][0] == 1)?1:0;
        }

        // Filling the values for the first row
        for (int i = 1; i < C; i++) 
		{
            o[0][i] = (o[0][i] == 0 && o[0][i - 1] == 1)?1:0;
        }

        // Starting from cell(1,1) fill up the values
        // No. of ways of reaching cell[i][j] = cell[i - 1][j] + cell[i][j - 1]
        // i.e. From above and left.
        for (int i = 1; i < R; i++)
		{
            for (int j = 1; j < C; j++)
			{
                if (o[i][j] == 0) 
				{
                    o[i][j] = o[i - 1][j] + o[i][j - 1];
                } 
				else 
				{
                    o[i][j] = 0;
                }
            }
        }

        // Return value stored in rightmost bottommost cell. 
		// That is the destination.
        return o[R - 1][C - 1];
    }
	public static void main(String[] args) 
	{
		Scanner s=new Scanner(System.in);
		int r=s.nextInt();
		int c=s.nextInt();
		int o[][] = new int[r][c];
		for(int i=0;i<r;i++)
		{
			for(int j=0;j<c;j++)
			{
				o[i][j]=s.nextInt();
			}
		}
		System.out.println(uniquePathsWithObstacles(o));
	}
}

