/*
1338. Reduce Array Size to The Half
You are given an integer array arr. You can choose a set of integers and 
remove all the occurrences of these integers in the array.

Return the minimum size of the set so that at least half of the integers of the
array are removed.

Example 1:

Input: 
10
3 3 3 3 5 5 5 2 2 7
Output: 2
Explanation: Choosing {3,7} will make the new array [5,5,5,2,2] which has 
size 5 (i.e equal to half of the size of the old array).
Possible sets of size 2 are {3,5},{3,2},{5,2}.
Choosing set {2,7} is not possible as it will make the new array 
[3,3,3,3,5,5,5] which has a size greater than half of the size of the old array.

Example 2:

Input: 
6
7 7 7 7 7 7
Output: 1
Explanation: The only possible set you can choose is {7}. This will make the 
new array empty.

Intuition
Store the frequencies to remove the least size set but to satisfy the condition
remove the element with highest frequency

Approach
Initialise a HashMap and store elements and their frequencies
Intialise a priority queue (Max heap) so that higher frequencies are at the top
get the size of array
take k = size/2
initialise a count variable
pop till the size >= k
for each pop increment cout
At the end return the count
*/
import java.util.*;
class  RHalf
{
	public static int minSetSize(int[] arr) 
	{
    int size = arr.length;
    HashMap<Integer, Integer> hm = new HashMap<>();
    for (int i : arr) 
	{
        hm.put(i, hm.getOrDefault(i, 0) + 1);
    }

    PriorityQueue<Integer> pq = new PriorityQueue<>(
		new Comparator<Integer>() 
		{
        public int compare(Integer a, Integer b) 
		{
            return Integer.compare(b, a); // descending order
        }
    });

	for(Integer x:hm.values())
	{
		pq.add(x);
	}

    int count = 0;
    int k = size / 2;
    while (!pq.isEmpty()) 
	{
        count++;
        size -= pq.poll();
        if (size <= k) break;
    }

    return count;
}

	public static void main(String[] args) 
	{
		Scanner s=new Scanner(System.in);
		int n=s.nextInt();
		int a[]=new int[n];
		for(int i=0;i<n;i++)
			a[i]=s.nextInt();
		System.out.println(minSetSize(a));
	}
}

