/*
Write a Java program to convert numeric input into Indian Rupees in words.
Input: 300
Output: Three Hundred Rupees

Input: 10076662.32
Output: One Crore Seventy six Thousand Six Hundred Sixty-two Rupees and Thirty-two Paise
*/
import java.util.Scanner;

public class RupeesInWords {

    private static final String[] ones = {
        "", "One", "Two", "Three", "Four", "Five",
        "Six", "Seven", "Eight", "Nine", "Ten", "Eleven",
        "Twelve", "Thirteen", "Fourteen", "Fifteen", "Sixteen",
        "Seventeen", "Eighteen", "Nineteen"
    };

    private static final String[] tens = {
        "", "", "Twenty", "Thirty", "Forty", "Fifty",
        "Sixty", "Seventy", "Eighty", "Ninety"
    };

    private static String convertNumberToWords(int number) {
        if (number == 0) return "Zero";
        return convert(number).trim();
    }

    private static String convert(int number) {
        StringBuilder result = new StringBuilder();

        if (number >= 10000000) {
            result.append(convert(number / 10000000)).append(" Crore ");
            number %= 10000000;
        }
        if (number >= 100000) {
            result.append(convert(number / 100000)).append(" Lakh ");
            number %= 100000;
        }
        if (number >= 1000) {
            result.append(convert(number / 1000)).append(" Thousand ");
            number %= 1000;
        }
        if (number >= 100) {
            result.append(convert(number / 100)).append(" Hundred ");
            number %= 100;
        }
        if (number > 0) {
            if (number < 20) {
                result.append(ones[number]).append(" ");
            } else {
                result.append(tens[number / 10]).append(" ").append(ones[number % 10]).append(" ");
            }
        }

        return result.toString();
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        System.out.print("Enter amount: ");
        String amountStr = sc.next();

        String[] parts = amountStr.split("\\.");
        int rupees = Integer.parseInt(parts[0]);
        int paise = (parts.length > 1) ? Integer.parseInt((parts[1] + "00").substring(0, 2)) : 0;

        StringBuilder result = new StringBuilder();

        if (rupees > 0) {
            result.append(convertNumberToWords(rupees)).append(" Rupees");
        }
        if (paise > 0) {
            if (rupees > 0) result.append(" and ");
            result.append(convertNumberToWords(paise)).append(" Paise");
        }

        if (rupees == 0 && paise == 0) {
            result.append("Zero Rupees");
        }

        System.out.println(result.toString().trim());
    }
}

