import java.util.*;
public class SortColorsCounting 
{

    public static void sortColors(int[] arr) 
	{
        int count0 = 0, count1 = 0, count2 = 0;

        // First pass: count number of 0s, 1s, and 2s
        for (int num : arr) 
		{
            if (num == 0) count0++;
            else if (num == 1) count1++;
            else count2++;
        }

        // Second pass: overwrite array based on counts
        int i = 0;

        while (count0-- > 0) arr[i++] = 0;
        while (count1-- > 0) arr[i++] = 1;
        while (count2-- > 0) arr[i++] = 2;
    }


    public static void main(String[] args) 
	{
		Scanner s=new Scanner(System.in);
		int n=s.nextInt();
        int[] arr = new int[n];

		for(int i=0;i<n;i++)
		{
			arr[i]=s.nextInt();
		}


        sortColors(arr);

         for (int num : arr) {
            System.out.print(num + " ");
        }
    }
}

import java.util.*;

public class SortedArrayIntersectionWithSet {

    public static List<Integer> findIntersection(int[] arr1, int[] arr2) 
	{
        Set<Integer> set1 = new LinkedHashSet<>();
        Set<Integer> intersection = new LinkedHashSet<>();

        // Add all elements of arr1 to set
        for (int num : arr1) {
            set1.add(num);
        }

        // Check if elements of arr2 exist in set1
        for (int num : arr2) {
            if (set1.contains(num)) {
                intersection.add(num); // Ensures uniqueness
            }
        }

        // Convert to list 
        List<Integer> result = new ArrayList<>(intersection);

        return result;
    }

    public static void main(String[] args) 
	{
		Scanner s=new Scanner(System.in);
		int m=s.nextInt();
        int[] arr1 = new int[m];

		for(int i=0;i<m;i++)
			arr1[i]=s.nextInt();
		int n=s.nextInt();
        int[] arr2 = new int[n];
		for(int i=0;i<n;i++)
			arr2[i]=s.nextInt();
		List<Integer> result = findIntersection(arr1, arr2);
        System.out.println(result);
    }
}

