/*
The Tribonacci sequence Tn is defined as follows: 
T0 = 0, T1 = 1, T2 = 1, and Tn+3 = Tn + Tn+1 + Tn+2 for n >= 0.
Given n, write a java program to return the value of Tn using dynamic 
programming tabulation approach.


Example 1:

Input: n = 5
Output: 4
Explanation:
T_3 = 0 + 1 + 1 = 2
T_4 = 1 + 1 + 2 = 4

Example 2:
Input: n = 26
Output: 1389537
*/

import java.util.*;
class TriboNumber1 
{
	public static int tribonacci(int n) 
	{
        if (n < 4) 
		{
            return n > 1 ? 1 : 0;
        }

        int[] dp = new int[n + 1];
        dp[1] = 0;
        dp[2] = 1;
		dp[3] = 1;

        for (int i = 4; i <= n; ++i) 
		{
            dp[i] = dp[i - 1] + dp[i - 2] + dp[i - 3];
        }

        return dp[n];
    }
	public static void main(String[] args) 
	{
		Scanner s=new Scanner(System.in);
		int n=s.nextInt();
		System.out.println(tribonacci(n));
	}
}

