import java.util.*;
class  TruckUnits
{
	public static int maximumUnits(int[][] boxTypes, int truckSize) 
	{
        Arrays.sort(boxTypes, new Comparator<int[]>() 
		{
            public int compare(int[] a, int[] b) 
			{
                return b[1] - a[1]; // Sort in descending order of units per box
            }
