        int res = 0;
        for (int i = 0; i < boxTypes.length && truckSize > 0; i++) {
            int min = Math.min(truckSize, boxTypes[i][0]);
            truckSize -= min;
            res += min * boxTypes[i][1];
        }
        return res;
    }


