import java.util.*;
class  UniquePaths
{
	public static int uniquePaths(int m, int n) 
	{
        int[][] d = new int[m][n];

        for (int[] arr : d) 
		{
            Arrays.fill(arr, 1);
        }

		for(int r=1;r<m;r++)
			for(int c=1;c<n;c++)
			d[r][c]=d[r-1][c]+d[r][c-1];
